-- Smart Water Tank: the table the dashboard uses, and a day of real readings.
--
-- Import it into a database called water_level:
--
--     mysql water_level < water_level.sql
--
-- or create that database in phpMyAdmin and import this file into it. The
-- installer, setup_water_tank.sh, does both for you.
--
-- These are real readings from the tank this project was built for, over one
-- day: the tank empties through the morning, refills, and empties again. They
-- are dated 2026-09-01 and the dashboard links them under Sample data, so you
-- can compare a known day against whatever your own sensor is recording now.
--
-- Importing this file twice adds the sample day twice.

CREATE TABLE IF NOT EXISTS `level_log` (
  `id`        INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `level`     DECIMAL(6,3) NOT NULL COMMENT 'distance from the sensor down to the water, in cm',
  `date_time` DATETIME     NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_date_time` (`date_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;










-- The shape and size of the tank, set from the dashboard's Tank size page
-- rather than by editing a file.

CREATE TABLE IF NOT EXISTS `settings` (
  `name`  VARCHAR(32) NOT NULL,
  `value` VARCHAR(64) NOT NULL,
  PRIMARY KEY (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

